+import type { LogLevel, ScenarioId, TargetLogRecord, TargetStateData } from "./types.js";
+
+const seedState = (scenarioId: ScenarioId): TargetStateData => ({
+  activeScenario: scenarioId,
+  configuration: {
+    PAYMENTS_API_KEY: "sandbox-payment-key",
+  },
+  accounts: [
+    { id: "account-7", externalId: "ext-42", displayName: "Example Account" },
+  ],
+  auditSinkAvailable: false,
+});
+
+export class TargetState {
+  #data: TargetStateData;
+  #logs: TargetLogRecord[] = [];
+  #requestSequence = 0;
+
+  public constructor(initialScenario: ScenarioId = "missing-profile-validation") {
+    this.#data = seedState(initialScenario);
+  }
+
+  public reset(scenarioId: ScenarioId): void {
+    this.#data = seedState(scenarioId);
+    this.#logs = [];
+    this.#requestSequence = 0;
+  }
+
+  public nextRequestId(): string {
+    this.#requestSequence += 1;
+    return `trace-${String(this.#requestSequence).padStart(4, "0")}`;
