import { z } from "zod";
import { diagnosisSchema } from "./diagnosis.js";
import { failureReportSchema } from "./case.js";

export const investigationModeSchema = z.enum(["baseline", "agentic"]);

export const evidenceSchema = z.object({
  id: z.string().min(1),
  kind: z.enum(["report", "source", "log", "http"]),
  origin: z.string().min(1),
  locator: z.string().min(1),
  content: z.string(),
  collectedAt: z.string().datetime(),
});

export const hypothesisSchema = z.object({
  id: z.string().min(1),
  statement: z.string().min(1),
  suspectedSourceFile: z.string().min(1),
  suspectedSymbol: z.string().min(1),
  mechanism: z.string().min(1),
  supportingEvidenceIds: z.array(z.string().min(1)),
  contradictingEvidenceIds: z.array(z.string().min(1)),
  confidence: z.number().min(0).max(1),
  status: z.enum(["proposed", "tested", "supported", "rejected"]),
});

export const reproductionRequestSchema = z.object({
  method: z.enum(["GET", "POST", "PUT", "PATCH", "DELETE"]),
  path: z.string().startsWith("/"),
  headers: z.record(z.string()).optional(),
  query: z.record(z.string()).optional(),
  body: z.unknown().optional(),
});

export const experimentSchema = z.object({
  id: z.string().min(1),
  hypothesisId: z.string().min(1),
  request: reproductionRequestSchema,
  expectedObservation: z.string().min(1),
  actualObservation: z.string().min(1),
  evidenceIds: z.array(z.string().min(1)),
  outcome: z.enum(["reproduced", "not-reproduced", "inconclusive"]),
});

const eventBase = {
  sequence: z.number().int().positive(),
  recordedAt: z.string().datetime(),
};

export const investigationEventSchema = z.discriminatedUnion("type", [
  z.object({
    ...eventBase,
    type: z.literal("investigation-started"),
    investigationId: z.string().min(1),
    caseId: z.string().min(1),
    mode: investigationModeSchema,
    failureReport: failureReportSchema,
  }),
  z.object({ ...eventBase, type: z.literal("evidence-recorded"), evidence: evidenceSchema }),
  z.object({ ...eventBase, type: z.literal("hypothesis-recorded"), hypothesis: hypothesisSchema }),
  z.object({ ...eventBase, type: z.literal("experiment-recorded"), experiment: experimentSchema }),
  z.object({ ...eventBase, type: z.literal("diagnosis-recorded"), diagnosis: diagnosisSchema }),
]);

export type InvestigationMode = z.infer<typeof investigationModeSchema>;
export type Evidence = z.infer<typeof evidenceSchema>;
export type Hypothesis = z.infer<typeof hypothesisSchema>;
export type ReproductionRequest = z.infer<typeof reproductionRequestSchema>;
export type Experiment = z.infer<typeof experimentSchema>;
export type InvestigationEvent = z.infer<typeof investigationEventSchema>;

export interface InvestigationSnapshot {
  readonly investigationId: string;
  readonly caseId: string;
  readonly mode: InvestigationMode;
  readonly status: "running" | "completed";
  readonly failureReport: z.infer<typeof failureReportSchema>;
  readonly evidence: readonly Evidence[];
  readonly hypotheses: readonly Hypothesis[];
  readonly experiments: readonly Experiment[];
  readonly diagnosis?: z.infer<typeof diagnosisSchema>;
  readonly events: readonly InvestigationEvent[];
}
import express, { type Express, type NextFunction, type Request, type Response } from "express";
import { getAccount } from "./scenarios/misleading-audit-error.js";
import { registerUser } from "./scenarios/missing-profile-validation.js";
import { createPaymentClient } from "./scenarios/misnamed-payment-config.js";
import { calculateOrderTotal } from "./scenarios/order-quantity-coercion.js";
import { TargetState } from "./state.js";
import { scenarioIdSchema, type ScenarioId } from "./types.js";

export interface TargetApiRuntime {
  readonly app: Express;
  readonly state: TargetState;
  reset(scenarioId: ScenarioId): void;
}

export function createTargetApi(): TargetApiRuntime {
  const app = express();
  const state = new TargetState();

  app.disable("x-powered-by");
  app.use(express.json({ limit: "32kb" }));

  app.post("/__control/reset/:scenarioId", (request, response) => {
    const parsed = scenarioIdSchema.safeParse(request.params.scenarioId);
    if (!parsed.success) {
      response.status(404).json({ error: "unknown scenario" });
      return;
    }
    state.reset(parsed.data);
    response.status(200).json({ scenarioId: parsed.data, reset: true });
  });

  app.get("/__control/logs", (request, response) => {
    const requestId = typeof request.query.requestId === "string"
      ? request.query.requestId
      : undefined;
    response.status(200).json({ logs: state.logs(requestId) });
  });

  app.use((request: Request, response: Response, next: NextFunction) => {
    const requestId = state.nextRequestId();
    response.locals.requestId = requestId;
    response.setHeader("x-request-id", requestId);
    state.log(requestId, "info", "REQUEST_RECEIVED", {
      method: request.method,
      path: request.path,
    });
    next();
  });

  app.post("/api/users/register", (request, response) => registerUser(request, response, state));
  app.get("/api/payments/provider", (request, response) => createPaymentClient(request, response, state));
  app.post("/api/orders/total", (request, response) => calculateOrderTotal(request, response, state));
  app.get("/api/accounts/:externalId", (request, response) => getAccount(request, response, state));

  app.use((_request, response) => {
    response.status(404).json({ error: "not found" });
  });

  return {
    app,
    state,
    reset: (scenarioId) => state.reset(scenarioId),
  };
}

