+    const code: ToolErrorCode = error.code === "PATH_TRAVERSAL"
+      ? "PATH_TRAVERSAL"
+      : error.code === "FILE_NOT_FOUND"
+        ? "NOT_FOUND"
+        : error.code === "READ_LIMIT_EXCEEDED"
