+    const parsed = readSourceInputSchema.parse(input);
+    if (parsed.endLine !== undefined && parsed.endLine < parsed.startLine) {
+      throw new z.ZodError([{
+        code: "custom",
+        path: ["endLine"],
+        message: "endLine must be greater than or equal to startLine",
+      }]);
+    }
