+    kind,
+    ok: result.ok,
+    durationMs: result.durationMs,
+    ...(result.usage === undefined ? {} : { usage: result.usage }),
+    ...(result.providerRequestId === undefined ? {} : { providerRequestId: result.providerRequestId }),
+    ...(result.ok ? {} : {
