import type { Request, Response } from "express";
import type { TargetState } from "../state.js";

export function registerUser(request: Request, response: Response, state: TargetState): void {
  const requestId = response.locals.requestId as string;

  try {
    // Intentional fixture bug: profile and name are used before validation.
    const normalizedName = (request.body as { profile: { name: string } }).profile.name.trim();
    response.status(201).json({ id: "user-100", name: normalizedName });
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Unknown registration error";
    state.log(requestId, "error", "USER_REGISTRATION_UNHANDLED", { message });
    response.status(500).json({ error: "user registration failed", requestId });
  }
}
import type { Request, Response } from "express";
import type { TargetState } from "../state.js";

export function createPaymentClient(
  _request: Request,
  response: Response,
  state: TargetState,
): void {
  const requestId = response.locals.requestId as string;
  // Intentional fixture bug: seeded configuration uses PAYMENTS_API_KEY.
  const apiKey = state.data().configuration.PAYMENT_API_KEY;

  if (apiKey === undefined) {
    state.log(requestId, "error", "PAYMENT_CLIENT_CONFIGURATION_MISSING", {
      key: "PAYMENT_API_KEY",
    });
    response.status(503).json({ error: "payment provider unavailable", requestId });
    return;
  }

  response.status(200).json({ provider: "sandbox", configured: true });
}
import type { Request, Response } from "express";
import type { TargetState } from "../state.js";

export function calculateOrderTotal(
  request: Request,
  response: Response,
  state: TargetState,
): void {
  const requestId = response.locals.requestId as string;
  const body = request.body as { unitPrice?: unknown; quantity?: unknown };

  // Intentional fixture bug: quantity is not converted from its JSON string representation.
  const total = (body.unitPrice as number) + (body.quantity as number);
  if (typeof total !== "number" || !Number.isFinite(total)) {
    state.log(requestId, "error", "ORDER_TOTAL_INVALID_TYPE", {
      unitPriceType: typeof body.unitPrice,
      quantityType: typeof body.quantity,
      computedType: typeof total,
      computedValue: total,
    });
    response.status(500).json({ error: "order total calculation failed", requestId });
    return;
  }

  response.status(200).json({ total });
}
import type { Request, Response } from "express";
import type { TargetState } from "../state.js";

export function findAccountByExternalId(externalId: string, state: TargetState) {
  // Intentional fixture bug: compares the internal id instead of externalId.
  return state.data().accounts.find((account) => account.id === externalId);
}

function publishLookupFailureAudit(state: TargetState): void {
  if (!state.data().auditSinkAvailable) {
    throw new Error("audit sink connection refused");
  }
}

export function getAccount(request: Request, response: Response, state: TargetState): void {
  const requestId = response.locals.requestId as string;
  const rawExternalId = request.params.externalId;
  const externalId = Array.isArray(rawExternalId)
    ? rawExternalId[0] ?? ""
    : rawExternalId ?? "";
  const account = findAccountByExternalId(externalId, state);

  if (account === undefined) {
    state.log(requestId, "warn", "ACCOUNT_LOOKUP_RETURNED_NO_RESULT", { externalId });
    try {
      publishLookupFailureAudit(state);
    } catch (error: unknown) {
      state.log(requestId, "error", "AUDIT_PIPELINE_FATAL_DELIVERY_FAILURE", {
        message: error instanceof Error ? error.message : "unknown audit failure",
      });
    }
    response.status(500).json({ error: "account resolution failed", requestId });
    return;
  }

  response.status(200).json(account);
}
