import { mkdir, rename, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import type { ArtifactHashes } from "../artifacts/types.js";
import type { RunMetadata } from "../domain/run-metadata.js";
import type { TokenUsage } from "../llm/types.js";
import { canonicalJson } from "./serializer.js";
import type { BaselineDiagnosis } from "./schema.js";

export interface BaselineCallRecord {
  readonly kind: "reasoning" | "format-retry";
  readonly ok: boolean;
  readonly durationMs: number;
  readonly usage?: TokenUsage;
  readonly providerRequestId?: string;
  readonly error?: {
    readonly code: string;
    readonly message: string;
    readonly retryable: boolean;
  };
}

export interface BaselineResultArtifact {
  readonly schemaVersion: "baseline-result-v1";
  readonly runId: string;
  readonly status: "completed" | "failed";
  readonly caseId: string;
  readonly promptVersion: string;
  readonly model: string;
  readonly temperature: number;
  readonly artifactHashes: ArtifactHashes;
  readonly aggregateArtifactHash: string;
  readonly serializedContextHash: string;
  readonly diagnosis: BaselineDiagnosis | null;
  readonly evidenceValidation: {
    readonly supported: readonly string[];
    readonly unsupported: readonly string[];
  };
  readonly tokenUsage: TokenUsage;
  readonly durationMs: number;
  readonly providerRequestId?: string;
  readonly formatRetryCount: 0 | 1;
  readonly calls: readonly BaselineCallRecord[];
  readonly runMetadata: RunMetadata;
  readonly error?: {
    readonly code: string;
    readonly message: string;
    readonly retryable: boolean;
  };
}

function secretValues(environment: NodeJS.ProcessEnv): readonly string[] {
  return Object.entries(environment)
    .filter(([name, value]) => value !== undefined
      && value.length >= 4
      && /(api.?key|token|secret|password|credential)/iu.test(name))
    .map(([, value]) => value as string)
    .sort((left, right) => right.length - left.length);
}

function redact(value: unknown, secrets: readonly string[]): unknown {
  if (typeof value === "string") {
    return secrets.reduce((result, secret) => result.replaceAll(secret, "[REDACTED]"), value);
  }
  if (Array.isArray(value)) {
    return value.map((item) => redact(item, secrets));
  }
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>).map(([key, child]) => [key, redact(child, secrets)]),
    );
  }
  return value;
}

export function serializeBaselineResult(
  result: BaselineResultArtifact,
  environment: NodeJS.ProcessEnv = process.env,
): string {
  return `${canonicalJson(redact(result, secretValues(environment)))}\n`;
}

export async function writeBaselineResult(
  result: BaselineResultArtifact,
  resultsRoot: string,
  environment: NodeJS.ProcessEnv = process.env,
): Promise<string> {
  await mkdir(resultsRoot, { recursive: true });
  const safeRunId = result.runId.replace(/[^a-zA-Z0-9._-]/gu, "_");
  const destination = resolve(resultsRoot, `${safeRunId}.json`);
  const temporary = resolve(resultsRoot, `.${safeRunId}.tmp`);
  await writeFile(temporary, serializeBaselineResult(result, environment), { encoding: "utf8", flag: "wx" });
  await rename(temporary, destination);
  return destination;
}
import type { CaseArtifacts } from "../artifacts/types.js";
import { loadRuntimeScenario } from "../target-api/runtime-map.js";
import type { ExecuteReproductionData } from "../tools/execute-reproduction.js";
import { createExecuteReproductionTool } from "../tools/execute-reproduction.js";
import type { ReadSourceData } from "../tools/read-source.js";
import { createReadSourceTool } from "../tools/read-source.js";
import type { SearchLogsData } from "../tools/search-logs.js";
import { createSearchLogsTool } from "../tools/search-logs.js";
import type { SearchSourceData } from "../tools/search-source.js";
import { createSearchSourceTool } from "../tools/search-source.js";
import type { ToolResult, ToolRuntimeOptions } from "../tools/contracts.js";
import type { ReproductionRequest } from "../domain/investigation.js";

export interface AgenticTools {
  searchSource(input: unknown): Promise<ToolResult<SearchSourceData>>;
  readSource(input: unknown): Promise<ToolResult<ReadSourceData>>;
  searchLogs(input: unknown): Promise<ToolResult<SearchLogsData>>;
  executeReproduction(input: {
    request: ReproductionRequest;
    expectations: { status: number; bodyContains: string; logContains: readonly string[] };
  }): Promise<ToolResult<ExecuteReproductionData>>;
}

export async function createAgenticTools(input: {
  artifacts: CaseArtifacts;
  workspaceRoot: string;
  baseUrl: string;
  runtime?: ToolRuntimeOptions;
}): Promise<AgenticTools> {
  const scenarioId = await loadRuntimeScenario(input.workspaceRoot, input.artifacts.caseId);
  const reproduction = createExecuteReproductionTool({ baseUrl: input.baseUrl, ...input.runtime });
  return {
    searchSource: createSearchSourceTool(input.artifacts, input.runtime),
    readSource: createReadSourceTool(input.artifacts, input.workspaceRoot, input.runtime),
    searchLogs: createSearchLogsTool(input.artifacts, input.runtime),
    executeReproduction: async (request) => reproduction({ scenarioId, ...request }),
  };
}
import { z } from "zod";
import { faultCategorySchema } from "../domain/diagnosis.js";
import { reproductionRequestSchema } from "../domain/investigation.js";

export const agentHypothesisSchema = z.object({
  id: z.string().regex(/^hyp-[a-zA-Z0-9_-]+$/u),
  statement: z.string().min(1),
  faultCategory: faultCategorySchema,
  suspectedFile: z.string().min(1),
  suspectedSymbol: z.string().min(1),
  mechanism: z.string().min(1),
  supportingEvidenceIds: z.array(z.string().min(1)),
  contradictingEvidenceIds: z.array(z.string().min(1)),
  confidence: z.number().min(0).max(1),
  verificationPlan: z.string().min(1),
}).strict();

const reason = z.string().min(1);
export const investigatorDecisionSchema = z.discriminatedUnion("action", [
  z.object({ action: z.literal("search_source"), arguments: z.object({ query: z.string().min(1), maxMatches: z.number().int().min(1).max(50).optional() }).strict(), reason }).strict(),
  z.object({ action: z.literal("read_source"), arguments: z.object({ path: z.string().min(1), startLine: z.number().int().positive().optional(), endLine: z.number().int().positive().optional() }).strict(), reason }).strict(),
  z.object({ action: z.literal("search_logs"), arguments: z.object({ query: z.string().min(1), maxMatches: z.number().int().min(1).max(50).optional(), contextLines: z.number().int().min(0).max(3).optional() }).strict(), reason }).strict(),
  z.object({ action: z.literal("propose_hypotheses"), arguments: z.object({ hypotheses: z.array(agentHypothesisSchema).min(1).max(3) }).strict(), reason }).strict(),
  z.object({ action: z.literal("request_reproduction"), arguments: z.object({ hypothesisId: z.string().min(1) }).strict(), reason }).strict(),
  z.object({ action: z.literal("finish_inconclusive"), arguments: z.object({ explanation: z.string().min(1) }).strict(), reason }).strict(),
]);

export const reproducerDecisionSchema = z.object({
  hypothesisId: z.string().min(1),
  request: reproductionRequestSchema,
  expected: z.object({
    status: z.number().int().min(100).max(599).optional(),
    bodyContains: z.string().min(1).optional(),
    logContains: z.array(z.string().min(1)).max(20).default([]),
  }).strict(),
  reason: z.string().min(1),
}).strict();

export const verifierDecisionSchema = z.object({
  outcome: z.enum(["verified", "insufficient_evidence", "contradiction"]),
  hypothesisId: z.string().min(1),
  explanation: z.string().min(1),
  evidenceIds: z.array(z.string().min(1)),
  missingEvidenceRequest: z.string().nullable(),
  unsupportedClaims: z.array(z.string()),
}).strict();

export type AgentHypothesis = z.infer<typeof agentHypothesisSchema>;
export type InvestigatorDecision = z.infer<typeof investigatorDecisionSchema>;
export type ReproducerDecision = z.infer<typeof reproducerDecisionSchema>;
export type VerifierDecision = z.infer<typeof verifierDecisionSchema>;

export const INVESTIGATOR_JSON_SCHEMA = { type: "object", additionalProperties: false, required: ["action", "arguments", "reason"], properties: { action: { type: "string", enum: ["search_source", "read_source", "search_logs", "propose_hypotheses", "request_reproduction", "finish_inconclusive"] }, arguments: { type: "object" }, reason: { type: "string" } } } as const;
export const REPRODUCER_JSON_SCHEMA = { type: "object", additionalProperties: false, required: ["hypothesisId", "request", "expected", "reason"], properties: { hypothesisId: { type: "string" }, request: { type: "object" }, expected: { type: "object" }, reason: { type: "string" } } } as const;
export const VERIFIER_JSON_SCHEMA = { type: "object", additionalProperties: false, required: ["outcome", "hypothesisId", "explanation", "evidenceIds", "missingEvidenceRequest", "unsupportedClaims"], properties: { outcome: { type: "string", enum: ["verified", "insufficient_evidence", "contradiction"] }, hypothesisId: { type: "string" }, explanation: { type: "string" }, evidenceIds: { type: "array", items: { type: "string" } }, missingEvidenceRequest: { type: ["string", "null"] }, unsupportedClaims: { type: "array", items: { type: "string" } } } } as const;

