import { z } from "zod";
import { LlmProviderError, type LlmProvider, type RawLlmResponse } from "./types.js";

const responseSchema = z.object({
  id: z.string().optional(),
  status: z.string().optional(),
  error: z.object({ code: z.string().optional(), message: z.string() }).nullish(),
  incomplete_details: z.object({ reason: z.string().optional() }).nullish(),
  output: z.array(z.object({
    type: z.string(),
    content: z.array(z.object({
      type: z.string(),
      text: z.string().optional(),
    }).passthrough()).optional(),
  }).passthrough()).optional(),
  usage: z.object({
    input_tokens: z.number().int().nonnegative(),
    output_tokens: z.number().int().nonnegative(),
    total_tokens: z.number().int().nonnegative(),
  }).optional(),
}).passthrough();

export interface OpenAiResponsesProviderOptions {
  readonly baseUrl?: string;
  readonly fetchImplementation?: typeof fetch;
}

function sanitize(message: string, secret: string): string {
  return secret === "" ? message : message.replaceAll(secret, "[REDACTED]");
}

function isRetryableStatus(status: number): boolean {
  return status === 408 || status === 409 || status === 429 || status >= 500;
}

export class OpenAiResponsesProvider implements LlmProvider {
  public readonly providerId = "openai-responses";
  readonly #baseUrl: string;
  readonly #fetch: typeof fetch;

  public constructor(options: OpenAiResponsesProviderOptions = {}) {
    this.#baseUrl = (options.baseUrl ?? "https://api.openai.com/v1").replace(/\/$/u, "");
    this.#fetch = options.fetchImplementation ?? fetch;
  }

  public async invoke(input: Parameters<LlmProvider["invoke"]>[0]): Promise<RawLlmResponse> {
    const apiKey = process.env.OPENAI_API_KEY ?? "";
    if (apiKey.trim() === "") {
      throw new LlmProviderError("missing_api_key", "OPENAI_API_KEY is not configured", false);
    }

    let response: Response;
    try {
      response = await this.#fetch(`${this.#baseUrl}/responses`, {
        method: "POST",
        headers: {
          authorization: `Bearer ${apiKey}`,
          "content-type": "application/json",
        },
        body: JSON.stringify({
          model: input.configuration.modelId,
          temperature: input.configuration.temperature,
          input: input.messages.map((message) => ({ role: message.role, content: message.content })),
          text: {
            format: {
              type: "json_schema",
              name: input.responseSchemaName,
              strict: true,
              schema: input.responseJsonSchema,
            },
          },
          tools: [],
          tool_choice: "none",
          store: false,
        }),
        signal: AbortSignal.timeout(input.configuration.timeoutMs),
      });
    } catch (error: unknown) {
      const message = sanitize(error instanceof Error ? error.message : "OpenAI request failed", apiKey);
      const timedOut = error instanceof Error && (error.name === "AbortError" || error.name === "TimeoutError");
      throw new LlmProviderError(timedOut ? "timeout" : "network_error", message, true);
    }

    const responseText = await response.text();
    if (Buffer.byteLength(responseText, "utf8") > 2 * 1024 * 1024) {
      throw new LlmProviderError("response_too_large", "OpenAI response exceeded the 2 MiB limit", false);
    }
    let responseJson: unknown;
    try {
      responseJson = JSON.parse(responseText);
    } catch {
      throw new LlmProviderError("invalid_response", `OpenAI returned non-JSON HTTP ${response.status}`, isRetryableStatus(response.status));
    }
    const parsed = responseSchema.safeParse(responseJson);
    if (!parsed.success) {
      throw new LlmProviderError("invalid_response", "OpenAI returned an unexpected response shape", false);
    }
    if (!response.ok || parsed.data.error !== null && parsed.data.error !== undefined) {
      const providerCode = parsed.data.error?.code ?? `http_${response.status}`;
      const message = sanitize(parsed.data.error?.message ?? `OpenAI returned HTTP ${response.status}`, apiKey);
      throw new LlmProviderError(providerCode, message, isRetryableStatus(response.status));
    }
    if (parsed.data.status !== undefined && parsed.data.status !== "completed") {
      throw new LlmProviderError(
        parsed.data.incomplete_details?.reason ?? `response_${parsed.data.status}`,
        `OpenAI response did not complete: ${parsed.data.status}`,
        parsed.data.status === "in_progress" || parsed.data.status === "queued",
      );
    }

    const outputText = parsed.data.output
      ?.flatMap((item) => item.type === "message" ? item.content ?? [] : [])
      .find((content) => content.type === "output_text")
      ?.text;
    if (outputText === undefined) {
      throw new LlmProviderError("missing_output", "OpenAI response contained no structured output text", false);
    }
    return {
      output: outputText,
      ...(parsed.data.usage === undefined ? {} : {
        usage: {
          inputTokens: parsed.data.usage.input_tokens,
          outputTokens: parsed.data.usage.output_tokens,
          totalTokens: parsed.data.usage.total_tokens,
        },
      }),
      ...(parsed.data.id === undefined ? {} : { providerRequestId: parsed.data.id }),
    };
  }
}
import { performance } from "node:perf_hooks";
import { z } from "zod";
import {
  llmConfigurationSchema,
  llmMessageSchema,
  LlmProviderError,
  tokenUsageSchema,
  type LlmConfiguration,
  type LlmMessage,
  type LlmProvider,
  type StructuredLlmResult,
} from "./types.js";

export interface StructuredLlmRequest<T> {
  readonly configuration: LlmConfiguration;
  readonly messages: readonly LlmMessage[];
  readonly responseSchemaName: string;
  readonly responseSchema: z.ZodType<T, z.ZodTypeDef, unknown>;
  readonly responseJsonSchema: Readonly<Record<string, unknown>>;
}

function duration(started: number): number {
  return Math.round((performance.now() - started) * 1_000) / 1_000;
}

function parseOutput(output: unknown): unknown {
  if (typeof output !== "string") {
    return output;
  }
  return JSON.parse(output);
}

export async function generateStructured<T>(
  provider: LlmProvider,
  request: StructuredLlmRequest<T>,
): Promise<StructuredLlmResult<T>> {
  const started = performance.now();
  const configuration = llmConfigurationSchema.safeParse(request.configuration);
  const messages = z.array(llmMessageSchema).safeParse(request.messages);
  if (!configuration.success || !messages.success || request.responseSchemaName.trim() === "") {
    return {
      ok: false,
      error: { code: "INVALID_CONFIGURATION", message: "Invalid LLM configuration or request", retryable: false },
      providerId: provider.providerId,
      modelId: request.configuration.modelId,
      durationMs: duration(started),
    };
  }

  let timeout: NodeJS.Timeout | undefined;
  try {
    const timeoutPromise = new Promise<never>((_resolve, reject) => {
      timeout = setTimeout(() => reject(new LlmProviderError("timeout", "LLM request timed out", true)), configuration.data.timeoutMs);
    });
    const response = await Promise.race([
      provider.invoke({
        configuration: configuration.data,
        messages: messages.data,
        responseSchemaName: request.responseSchemaName,
        responseJsonSchema: request.responseJsonSchema,
      }),
      timeoutPromise,
    ]);
    const parsedUsage = response.usage === undefined ? undefined : tokenUsageSchema.safeParse(response.usage);
    if (parsedUsage !== undefined && !parsedUsage.success) {
      return {
        ok: false,
        error: { code: "PROVIDER_ERROR", message: "Provider returned invalid usage metadata", retryable: false },
        providerId: provider.providerId,
        modelId: configuration.data.modelId,
        ...(response.providerRequestId === undefined ? {} : { providerRequestId: response.providerRequestId }),
        durationMs: duration(started),
      };
    }
    let output: unknown;
    try {
      output = parseOutput(response.output);
    } catch {
      return {
        ok: false,
        error: {
          code: "INVALID_STRUCTURED_OUTPUT",
          message: "Provider output is not valid JSON",
          retryable: false,
          invalidOutput: response.output,
        },
        providerId: provider.providerId,
        modelId: configuration.data.modelId,
        ...(parsedUsage?.success === true ? { usage: parsedUsage.data } : {}),
        ...(response.providerRequestId === undefined ? {} : { providerRequestId: response.providerRequestId }),
        durationMs: duration(started),
      };
    }
    const structured = request.responseSchema.safeParse(output);
    if (!structured.success) {
      return {
        ok: false,
        error: {
          code: "INVALID_STRUCTURED_OUTPUT",
          message: structured.error.issues[0]?.message ?? "Provider output failed schema validation",
          retryable: false,
          invalidOutput: output,
        },
        providerId: provider.providerId,
        modelId: configuration.data.modelId,
        ...(parsedUsage?.success === true ? { usage: parsedUsage.data } : {}),
        ...(response.providerRequestId === undefined ? {} : { providerRequestId: response.providerRequestId }),
        durationMs: duration(started),
      };
    }
    return {
      ok: true,
      value: structured.data,
      ...(parsedUsage?.success === true ? { usage: parsedUsage.data } : {}),
      providerId: provider.providerId,
      modelId: configuration.data.modelId,
      ...(response.providerRequestId === undefined ? {} : { providerRequestId: response.providerRequestId }),
      durationMs: duration(started),
    };
  } catch (error: unknown) {
    if (error instanceof LlmProviderError) {
      return {
        ok: false,
        error: {
          code: error.providerCode === "timeout" ? "TIMEOUT" : "PROVIDER_ERROR",
          message: error.message,
          retryable: error.retryable,
          providerCode: error.providerCode,
        },
        providerId: provider.providerId,
        modelId: configuration.data.modelId,
        durationMs: duration(started),
      };
    }
    return {
      ok: false,
      error: {
        code: "PROVIDER_ERROR",
        message: error instanceof Error ? error.message : "Unknown provider error",
        retryable: false,
      },
      providerId: provider.providerId,
      modelId: configuration.data.modelId,
      durationMs: duration(started),
    };
  } finally {
    if (timeout !== undefined) {
      clearTimeout(timeout);
    }
  }
}
