import { z } from "zod";
import { faultCategorySchema } from "../domain/diagnosis.js";
import { reproductionRequestSchema } from "../domain/investigation.js";

export const agentHypothesisSchema = z.object({
  id: z.string().regex(/^hyp-[a-zA-Z0-9_-]+$/u),
  statement: z.string().min(1),
  faultCategory: faultCategorySchema,
  suspectedFile: z.string().min(1),
  suspectedSymbol: z.string().min(1),
  mechanism: z.string().min(1),
  supportingEvidenceIds: z.array(z.string().min(1)),
  contradictingEvidenceIds: z.array(z.string().min(1)),
  confidence: z.number().min(0).max(1),
  verificationPlan: z.string().min(1),
}).strict();

const reason = z.string().min(1);
export const investigatorDecisionSchema = z.discriminatedUnion("action", [
  z.object({ action: z.literal("search_source"), arguments: z.object({ query: z.string().min(1), maxMatches: z.number().int().min(1).max(50).optional() }).strict(), reason }).strict(),
  z.object({ action: z.literal("read_source"), arguments: z.object({ path: z.string().min(1), startLine: z.number().int().positive().optional(), endLine: z.number().int().positive().optional() }).strict(), reason }).strict(),
  z.object({ action: z.literal("search_logs"), arguments: z.object({ query: z.string().min(1), maxMatches: z.number().int().min(1).max(50).optional(), contextLines: z.number().int().min(0).max(3).optional() }).strict(), reason }).strict(),
  z.object({ action: z.literal("propose_hypotheses"), arguments: z.object({ hypotheses: z.array(agentHypothesisSchema).min(1).max(3) }).strict(), reason }).strict(),
  z.object({ action: z.literal("request_reproduction"), arguments: z.object({ hypothesisId: z.string().min(1) }).strict(), reason }).strict(),
  z.object({ action: z.literal("finish_inconclusive"), arguments: z.object({ explanation: z.string().min(1) }).strict(), reason }).strict(),
]);

export const reproducerDecisionSchema = z.object({
  hypothesisId: z.string().min(1),
  request: reproductionRequestSchema,
  expected: z.object({
    status: z.number().int().min(100).max(599).optional(),
    bodyContains: z.string().min(1).optional(),
    logContains: z.array(z.string().min(1)).max(20).default([]),
  }).strict(),
  reason: z.string().min(1),
}).strict();

export const verifierDecisionSchema = z.object({
  outcome: z.enum(["verified", "insufficient_evidence", "contradiction"]),
  hypothesisId: z.string().min(1),
  explanation: z.string().min(1),
  evidenceIds: z.array(z.string().min(1)),
  missingEvidenceRequest: z.string().nullable(),
  unsupportedClaims: z.array(z.string()),
}).strict();

export type AgentHypothesis = z.infer<typeof agentHypothesisSchema>;
export type InvestigatorDecision = z.infer<typeof investigatorDecisionSchema>;
export type ReproducerDecision = z.infer<typeof reproducerDecisionSchema>;
export type VerifierDecision = z.infer<typeof verifierDecisionSchema>;

const strictObject = (properties: Readonly<Record<string, unknown>>, required = Object.keys(properties)) => ({
  type: "object", additionalProperties: false, properties, required,
});
const hypothesisJsonSchema = strictObject({
  id: { type: "string" }, statement: { type: "string" },
  faultCategory: { type: "string", enum: ["input-validation", "configuration", "type-coercion", "data-access", "authentication", "downstream-service", "concurrency", "unknown"] },
  suspectedFile: { type: "string" }, suspectedSymbol: { type: "string" }, mechanism: { type: "string" },
  supportingEvidenceIds: { type: "array", items: { type: "string" } }, contradictingEvidenceIds: { type: "array", items: { type: "string" } },
  confidence: { type: "number" }, verificationPlan: { type: "string" },
});
export const INVESTIGATOR_JSON_SCHEMA = strictObject({
  action: { type: "string", enum: ["search_source", "read_source", "search_logs", "propose_hypotheses", "request_reproduction", "finish_inconclusive"] },
  arguments: { anyOf: [
    strictObject({ query: { type: "string" } }),
    strictObject({ path: { type: "string" } }),
    strictObject({ hypotheses: { type: "array", items: hypothesisJsonSchema } }),
    strictObject({ hypothesisId: { type: "string" } }),
    strictObject({ explanation: { type: "string" } }),
  ] },
  reason: { type: "string" },
});
export const REPRODUCER_JSON_SCHEMA = strictObject({
  hypothesisId: { type: "string" },
  request: strictObject({
    method: { type: "string", enum: ["GET", "POST", "PUT", "PATCH", "DELETE"] }, path: { type: "string" },
    body: { type: ["object", "array", "string", "number", "boolean", "null"] },
  }),
  expected: strictObject({ status: { type: "integer" }, bodyContains: { type: "string" }, logContains: { type: "array", items: { type: "string" } } }),
  reason: { type: "string" },
});
export const VERIFIER_JSON_SCHEMA = { type: "object", additionalProperties: false, required: ["outcome", "hypothesisId", "explanation", "evidenceIds", "missingEvidenceRequest", "unsupportedClaims"], properties: { outcome: { type: "string", enum: ["verified", "insufficient_evidence", "contradiction"] }, hypothesisId: { type: "string" }, explanation: { type: "string" }, evidenceIds: { type: "array", items: { type: "string" } }, missingEvidenceRequest: { type: ["string", "null"] }, unsupportedClaims: { type: "array", items: { type: "string" } } } } as const;

import { performance } from "node:perf_hooks";
import { z } from "zod";
import {
  llmConfigurationSchema,
  llmMessageSchema,
  LlmProviderError,
  tokenUsageSchema,
  type LlmConfiguration,
  type LlmMessage,
  type LlmProvider,
  type StructuredLlmResult,
} from "./types.js";
import { effectiveLlmConfiguration } from "./model-capabilities.js";
import { buildStructuredOutputValidationDiagnostic } from "./structured-output-diagnostic.js";

export interface StructuredLlmRequest<T> {
  readonly configuration: LlmConfiguration;
  readonly messages: readonly LlmMessage[];
  readonly responseSchemaName: string;
  readonly responseSchema: z.ZodType<T, z.ZodTypeDef, unknown>;
  readonly responseJsonSchema: Readonly<Record<string, unknown>>;
}

function duration(started: number): number {
  return Math.round((performance.now() - started) * 1_000) / 1_000;
}

function parseOutput(output: unknown): unknown {
  if (typeof output !== "string") {
    return output;
  }
  return JSON.parse(output);
}

export async function generateStructured<T>(
  provider: LlmProvider,
  request: StructuredLlmRequest<T>,
): Promise<StructuredLlmResult<T>> {
  const started = performance.now();
  const configuration = llmConfigurationSchema.safeParse(effectiveLlmConfiguration(request.configuration));
  const messages = z.array(llmMessageSchema).safeParse(request.messages);
  if (!configuration.success || !messages.success || request.responseSchemaName.trim() === "") {
    return {
      ok: false,
      error: { code: "INVALID_CONFIGURATION", message: "Invalid LLM configuration or request", retryable: false },
      providerId: provider.providerId,
      modelId: request.configuration.modelId,
      durationMs: duration(started),
    };
  }

  let timeout: NodeJS.Timeout | undefined;
  try {
    const timeoutPromise = new Promise<never>((_resolve, reject) => {
      timeout = setTimeout(() => reject(new LlmProviderError("timeout", "LLM request timed out", true)), configuration.data.timeoutMs);
    });
    const response = await Promise.race([
      provider.invoke({
        configuration: configuration.data,
        messages: messages.data,
        responseSchemaName: request.responseSchemaName,
        responseJsonSchema: request.responseJsonSchema,
      }),
      timeoutPromise,
    ]);
    const parsedUsage = response.usage === undefined ? undefined : tokenUsageSchema.safeParse(response.usage);
    if (parsedUsage !== undefined && !parsedUsage.success) {
      return {
        ok: false,
        error: { code: "PROVIDER_ERROR", message: "Provider returned invalid usage metadata", retryable: false },
        providerId: provider.providerId,
        modelId: configuration.data.modelId,
        ...(response.providerRequestId === undefined ? {} : { providerRequestId: response.providerRequestId }),
        durationMs: duration(started),
      };
    }
    let output: unknown;
    try {
      output = parseOutput(response.output);
    } catch {
      return {
        ok: false,
        error: {
          code: "INVALID_JSON",
          message: "Provider output is not valid JSON",
          retryable: false,
          invalidOutput: response.output,
        },
        providerId: provider.providerId,
        modelId: configuration.data.modelId,
        ...(parsedUsage?.success === true ? { usage: parsedUsage.data } : {}),
        ...(response.providerRequestId === undefined ? {} : { providerRequestId: response.providerRequestId }),
        durationMs: duration(started),
      };
    }
    const structured = request.responseSchema.safeParse(output);
    if (!structured.success) {
      const validationDiagnostic = buildStructuredOutputValidationDiagnostic(output, structured.error.issues);
      const firstIssue = validationDiagnostic.validationIssues[0];
      return {
        ok: false,
        error: {
          code: "INVALID_STRUCTURED_OUTPUT",
          message: firstIssue === undefined
            ? "Provider output failed schema validation"
            : `Structured output failed validation at ${firstIssue.path.join(".") || "<root>"}: ${firstIssue.message}`,
          retryable: false,
          invalidOutput: output,
          validationDiagnostic,
        },
        providerId: provider.providerId,
        modelId: configuration.data.modelId,
        ...(parsedUsage?.success === true ? { usage: parsedUsage.data } : {}),
        ...(response.providerRequestId === undefined ? {} : { providerRequestId: response.providerRequestId }),
        durationMs: duration(started),
      };
    }
    return {
      ok: true,
      value: structured.data,
      ...(parsedUsage?.success === true ? { usage: parsedUsage.data } : {}),
      providerId: provider.providerId,
      modelId: configuration.data.modelId,
      ...(response.providerRequestId === undefined ? {} : { providerRequestId: response.providerRequestId }),
      durationMs: duration(started),
    };
  } catch (error: unknown) {
    if (error instanceof LlmProviderError) {
      return {
        ok: false,
        error: {
          code: error.providerCode === "timeout" ? "TIMEOUT" : "PROVIDER_ERROR",
          message: error.message,
          retryable: error.retryable,
          providerCode: error.providerCode,
        },
        providerId: provider.providerId,
        modelId: configuration.data.modelId,
        durationMs: duration(started),
      };
    }
    return {
      ok: false,
      error: {
        code: "PROVIDER_ERROR",
        message: error instanceof Error ? error.message : "Unknown provider error",
        retryable: false,
      },
      providerId: provider.providerId,
      modelId: configuration.data.modelId,
      durationMs: duration(started),
    };
  } finally {
    if (timeout !== undefined) {
      clearTimeout(timeout);
    }
  }
}

