import type { LlmMessage } from "../llm/types.js";
import { canonicalJson } from "../baseline/serializer.js";

export const INVESTIGATOR_PROMPT_VERSION = "investigator-v1";
export const REPRODUCER_PROMPT_VERSION = "reproducer-v1";
export const VERIFIER_PROMPT_VERSION = "verifier-v1";

const investigator = `You are TraceRoot's Investigator. Interpret symptoms and selectively inspect evidence. Return exactly one structured action. Maintain no more than three ranked causal hypotheses. A hypothesis must name a file, symbol, mechanism, supporting and contradicting evidence IDs, and a verification plan. You cannot declare verified, invent runtime behavior, cite unknown evidence, access private benchmark paths, or exceed the available actions. Request reproduction only for a concrete active hypothesis.`;
const reproducer = `You are TraceRoot's Reproducer. Given one concrete hypothesis, design the smallest controlled HTTP experiment that can support or reject it. State status, body, and log expectations before execution. Always include request body; use null when there is no body. You cannot execute anything yourself, modify source, use control endpoints, access private mappings or ground truth, or request shell commands. Return only the experiment specification.`;
const verifier = `You are TraceRoot's adversarial Verifier. Decide whether evidence establishes root cause rather than correlation. Check source support, matching runtime reproduction, upstream versus secondary symptoms, alternatives, contradictions, and unsupported claims. Confidence alone is insufficient. Return verified, insufficient_evidence with a precise missing-evidence request, or contradiction.`;

export function roleMessages(role: "investigator" | "reproducer" | "verifier", context: unknown): readonly LlmMessage[] {
  const system = role === "investigator" ? investigator : role === "reproducer" ? reproducer : verifier;
  return Object.freeze([{ role: "system", content: system }, { role: "user", content: canonicalJson(context) }]);
}

