          MAX_RESPONSE_BYTES,
        );
      } catch (error: unknown) {
        throw new ToolExecutionError(
          "TARGET_UNAVAILABLE",
          error instanceof Error ? `Target reset failed: ${error.message}` : "Target reset failed",
