  return Object.freeze({
    diagnosis: finalDiagnosis,
    terminationReason,
    unsupportedClaimCount: state.unsupported.size + state.unsupportedClaims.size,
    unsupportedReferences: Object.freeze([...state.unsupported]),
    unsupportedClaims: Object.freeze([...state.unsupportedClaims]),
    metrics: Object.freeze({
      llmCalls: state.llmCalls, tokenUsage: state.tokens,
    this.#assertRunning();
    const snapshot = this.snapshot();
    this.#assertEvidenceExists([
      ...hypothesis.supportingEvidenceIds,
      ...hypothesis.contradictingEvidenceIds,
    ]);
    this.#append({ type: "hypothesis-recorded", hypothesis: structuredClone(hypothesis) });
  }

  public recordExperiment(experiment: Experiment): void {
    experimentSchema.parse(experiment);
    this.#assertRunning();
    const snapshot = this.snapshot();
    if (!snapshot.hypotheses.some((item) => item.id === experiment.hypothesisId)) {
      throw new Error(`Unknown hypothesis id: ${experiment.hypothesisId}`);
    }
    if (snapshot.experiments.some((item) => item.id === experiment.id)) {
      throw new Error(`Experiment id already exists: ${experiment.id}`);
    }
    this.#assertEvidenceExists(experiment.evidenceIds);
    this.#append({ type: "experiment-recorded", experiment: structuredClone(experiment) });
  }

  public recordDiagnosis(diagnosis: Diagnosis): void {
    diagnosisSchema.parse(diagnosis);
    this.#assertRunning();
    this.#assertEvidenceExists(diagnosis.evidenceIds);
    this.#append({ type: "diagnosis-recorded", diagnosis: structuredClone(diagnosis) });
  }

  public recordAgentStep(step: Omit<AgentStep, "type" | "sequence" | "recordedAt">): void {
    this.#assertRunning();
    this.#assertEvidenceExists(step.evidenceIds);
    this.#append({ type: "agent-step-recorded", ...structuredClone(step) });
  }

  public events(): readonly InvestigationEvent[] {
    return Object.freeze(structuredClone(this.#events));
  }

  public snapshot(): InvestigationSnapshot {
    const events = this.events();
    const started = events[0];
    if (started?.type !== "investigation-started") {
      throw new Error("Investigation journal is missing its start event");
    }
    const diagnosisEvent = events.find((event) => event.type === "diagnosis-recorded");
    const diagnosis = diagnosisEvent?.type === "diagnosis-recorded"
      ? diagnosisEvent.diagnosis
      : undefined;

    return Object.freeze({
      investigationId: started.investigationId,
      caseId: started.caseId,
      mode: started.mode,
      status: diagnosis === undefined ? "running" : "completed",
      failureReport: structuredClone(started.failureReport),
      evidence: Object.freeze(events.flatMap((event) => event.type === "evidence-recorded" ? [event.evidence] : [])),
      hypotheses: Object.freeze(events.flatMap((event) => event.type === "hypothesis-recorded" ? [event.hypothesis] : [])),
      experiments: Object.freeze(events.flatMap((event) => event.type === "experiment-recorded" ? [event.experiment] : [])),
      ...(diagnosis === undefined ? {} : { diagnosis }),
      events,
    });
  }

  #snapshotEvidence(): readonly Evidence[] {
    return this.#events.flatMap((event) => event.type === "evidence-recorded" ? [event.evidence] : []);
  }

  #assertEvidenceExists(ids: readonly string[]): void {
    const known = new Set(this.#snapshotEvidence().map((item) => item.id));
    const missing = ids.find((id) => !known.has(id));
    if (missing !== undefined) {
      throw new Error(`Unknown evidence id: ${missing}`);
    }
  }

  #assertRunning(): void {
    if (this.#events.some((event) => event.type === "diagnosis-recorded")) {
      throw new Error("Investigation is already completed and cannot be modified");
    }
  }

  #append(event: UnrecordedEvent): void {
    const completeEvent = investigationEventSchema.parse({
      ...event,
      sequence: this.#events.length + 1,
      recordedAt: this.#clock().toISOString(),
    });
    this.#events.push(completeEvent);
  }
}
import type { CaseArtifacts } from "../artifacts/types.js";
import { loadRuntimeScenario } from "../target-api/runtime-map.js";
import type { ExecuteReproductionData } from "../tools/execute-reproduction.js";
import { createExecuteReproductionTool } from "../tools/execute-reproduction.js";
import type { ReadSourceData } from "../tools/read-source.js";
import { createReadSourceTool } from "../tools/read-source.js";
import type { SearchLogsData } from "../tools/search-logs.js";
import { createSearchLogsTool } from "../tools/search-logs.js";
import type { SearchSourceData } from "../tools/search-source.js";
import { createSearchSourceTool } from "../tools/search-source.js";
import type { ToolResult, ToolRuntimeOptions } from "../tools/contracts.js";
import type { ReproductionRequest } from "../domain/investigation.js";

export interface AgenticTools {
  searchSource(input: unknown): Promise<ToolResult<SearchSourceData>>;
  readSource(input: unknown): Promise<ToolResult<ReadSourceData>>;
  searchLogs(input: unknown): Promise<ToolResult<SearchLogsData>>;
  executeReproduction(input: {
    request: ReproductionRequest;
    expectations: { status: number; bodyContains: string; logContains: readonly string[] };
  }): Promise<ToolResult<ExecuteReproductionData>>;
}

export async function createAgenticTools(input: {
  artifacts: CaseArtifacts;
  workspaceRoot: string;
  baseUrl: string;
  runtime?: ToolRuntimeOptions;
}): Promise<AgenticTools> {
  const scenarioId = await loadRuntimeScenario(input.workspaceRoot, input.artifacts.caseId);
  const reproduction = createExecuteReproductionTool({ baseUrl: input.baseUrl, ...input.runtime });
  return {
    searchSource: createSearchSourceTool(input.artifacts, input.runtime),
    readSource: createReadSourceTool(input.artifacts, input.workspaceRoot, input.runtime),
    searchLogs: createSearchLogsTool(input.artifacts, input.runtime),
    executeReproduction: async (request) => reproduction({ scenarioId, ...request }),
  };
}

import type { Server } from "node:http";
