import { readFile } from "node:fs/promises";
import { beforeAll, describe, expect, it } from "vitest";
import { resolve } from "node:path";
import { ArtifactLoader } from "../../src/artifacts/loader.js";
import type { CaseArtifacts } from "../../src/artifacts/types.js";
import { runAgenticInvestigation, type AgenticLimits } from "../../src/agentic/orchestrator.js";
import type { AgenticTools } from "../../src/agentic/toolset.js";
import type { Evidence, ReproductionRequest } from "../../src/domain/investigation.js";
import { FakeLlmProvider } from "../../src/llm/fake-provider.js";
import { LlmProviderError, type RawLlmResponse } from "../../src/llm/types.js";
import type { ExecuteReproductionData } from "../../src/tools/execute-reproduction.js";
import type { ReadSourceData } from "../../src/tools/read-source.js";
import type { SearchLogsData } from "../../src/tools/search-logs.js";
import type { SearchSourceData } from "../../src/tools/search-source.js";
import { TOOL_VERSION, type ToolName, type ToolResult } from "../../src/tools/contracts.js";

const workspaceRoot = resolve(process.cwd());
const configuration = { modelId: "fake-agentic", temperature: 0, timeoutMs: 5_000 } as const;
const at = "2026-01-01T00:00:00.000Z";
let artifacts: CaseArtifacts;

beforeAll(async () => {
  const loaded = await new ArtifactLoader(workspaceRoot).load("case-001");
  if (!loaded.ok) throw new Error(loaded.error.message);
  artifacts = loaded.artifacts;
});

function response(output: unknown): RawLlmResponse {
  return { output, usage: { inputTokens: 10, outputTokens: 5, totalTokens: 15 }, providerRequestId: "fake-request" };
}

function hypothesis(id: string, evidenceIds: readonly string[], overrides: Record<string, unknown> = {}) {
  return {
    id,
    statement: `Hypothesis ${id}`,
    faultCategory: "input-validation",
    suspectedFile: "src/target-api/services/user-service.ts",
    suspectedSymbol: "registerUser",
    mechanism: "An unchecked optional value is dereferenced before persistence.",
    supportingEvidenceIds: [...evidenceIds],
    contradictingEvidenceIds: [],
    confidence: 0.8,
    verificationPlan: "Send the smallest request that omits the optional value and compare the failure signature.",
    ...overrides,
  };
}

const search = (query = "registerUser") => ({ action: "search_source", arguments: { query }, reason: "Locate relevant request handling source." });
const searchLogs = (query = "ERROR") => ({ action: "search_logs", arguments: { query }, reason: "Inspect the reported failure logs." });
const propose = (...items: ReturnType<typeof hypothesis>[]) => ({ action: "propose_hypotheses", arguments: { hypotheses: items }, reason: "Rank evidence-backed causes." });
const reproduce = (hypothesisId: string) => ({ action: "request_reproduction", arguments: { hypothesisId }, reason: "Test the concrete causal mechanism." });
const finish = (
  explanation = "No supported next action remains.",
  reason = "Evidence is insufficient.",
) => ({ action: "finish_inconclusive", arguments: { explanation }, reason });
const experiment = (hypothesisId: string, path = "/api/users/register") => ({
  hypothesisId,
  request: { method: "POST", path, body: { email: "test@example.com" } },
  expected: { status: 500, bodyContains: "failure", logContains: ["ERROR"] },
  reason: "Exercise the suspected branch with one controlled request.",
});
const verdict = (outcome: "verified" | "insufficient_evidence" | "contradiction", hypothesisId: string, evidenceIds: string[], missing: string | null = null) => ({
  outcome,
  hypothesisId,
  explanation: outcome === "verified" ? "Source and runtime evidence establish the same causal chain." : `${outcome} requires another investigation step.`,
  evidenceIds,
  missingEvidenceRequest: missing,
  unsupportedClaims: [],
});

function evidence(id: string, kind: Evidence["kind"], origin: ToolName): Evidence {
  return { id, kind, origin, locator: `case-001/${id}`, content: `observation:${id}`, collectedAt: at };
}

function success<T>(tool: ToolName, data: T, observations: readonly Evidence[]): ToolResult<T> {
  return { ok: true, tool, toolVersion: TOOL_VERSION, data, evidence: observations, durationMs: 1, truncated: false };
}

class ScriptedTools implements AgenticTools {
  public readonly calls: ToolName[] = [];
  public readonly requests: ReproductionRequest[] = [];
  public reproductionOutcomes: ExecuteReproductionData["outcome"][];
  #source = 0;
  #logs = 0;
  #reproductions = 0;

  public constructor(outcomes: ExecuteReproductionData["outcome"][] = ["reproduced"]) {
    this.reproductionOutcomes = [...outcomes];
  }

  public async searchSource(input: unknown): Promise<ToolResult<SearchSourceData>> {
    this.calls.push("search_source");
    this.#source += 1;
    return success("search_source", { query: JSON.stringify(input), matches: [], totalMatches: 1 }, [evidence(`ev-source-${this.#source}`, "source", "search_source")]);
  }

  public async readSource(_input: unknown): Promise<ToolResult<ReadSourceData>> {
    this.calls.push("read_source");
    this.#source += 1;
    return success("read_source", { path: "src/target-api/services/user-service.ts", startLine: 1, endLine: 2, content: "source", bytes: 6 }, [evidence(`ev-source-${this.#source}`, "source", "read_source")]);
  }

  public async searchLogs(input: unknown): Promise<ToolResult<SearchLogsData>> {
    this.calls.push("search_logs");
    this.#logs += 1;
    return success("search_logs", { query: JSON.stringify(input), matches: [], totalMatches: 1 }, [evidence(`ev-log-${this.#logs}`, "log", "search_logs")]);
  }

  public async executeReproduction(input: { request: ReproductionRequest; expectations: { status: number; bodyContains: string; logContains: readonly string[] } }): Promise<ToolResult<ExecuteReproductionData>> {
    this.calls.push("execute_reproduction");
    this.requests.push(input.request);
    this.#reproductions += 1;
    const outcome = this.reproductionOutcomes.shift() ?? "inconclusive";
    const data: ExecuteReproductionData = {
      outcome,
      correlationId: `correlation-${this.#reproductions}`,
      resetSucceeded: true,
      response: { status: outcome === "inconclusive" ? null : 500, body: { error: "failure" }, bodyText: "failure" },
      logs: [],
      assertions: [],
      ...(outcome === "inconclusive" ? { reason: "Target response unavailable" } : {}),
    };
    return success("execute_reproduction", data, [
      evidence(`ev-http-${this.#reproductions}`, "http", "execute_reproduction"),
      evidence(`ev-runtime-log-${this.#reproductions}`, "log", "execute_reproduction"),
    ]);
  }
}

class NoRuntimeEvidenceTools extends ScriptedTools {
  public override async executeReproduction(input: { request: ReproductionRequest; expectations: { status: number; bodyContains: string; logContains: readonly string[] } }): Promise<ToolResult<ExecuteReproductionData>> {
    this.calls.push("execute_reproduction");
    this.requests.push(input.request);
    return success("execute_reproduction", {
      outcome: "reproduced", correlationId: "correlation-no-evidence", resetSucceeded: true,
      response: { status: 500, body: { error: "failure" }, bodyText: "failure" }, logs: [], assertions: [],
    }, []);
  }
}

async function run(outputs: unknown[], tools = new ScriptedTools(), limits?: Partial<AgenticLimits>) {
  const provider = new FakeLlmProvider(outputs.map(response));
  const result = await runAgenticInvestigation({
    investigationId: "investigation-test",
    artifacts,
    provider,
    configuration,
    tools,
    ...(limits === undefined ? {} : { limits }),
    clock: () => new Date(at),
  });
  return { result, provider, tools };
}

function investigatorContexts(provider: FakeLlmProvider): Array<Record<string, unknown>> {
import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { Ajv } from "ajv";
import { describe, expect, it } from "vitest";
import {
  REPRODUCER_JSON_SCHEMA,
  VERIFIER_JSON_SCHEMA,
  reproducerDecisionSchema,
  reproducerProviderResponseSchema,
  verifierDecisionSchema,
} from "../../src/agentic/schemas.js";

const ajv = new Ajv({ allErrors: true, strict: true });
const validateReproducer = ajv.compile(REPRODUCER_JSON_SCHEMA);
const validateVerifier = ajv.compile(VERIFIER_JSON_SCHEMA);

function assertStrictObjectGraph(node: unknown, path = "$"): void {
  if (Array.isArray(node)) {
    node.forEach((child, index) => assertStrictObjectGraph(child, `${path}[${index}]`));
    return;
  }
  if (typeof node !== "object" || node === null) return;
  const schema = node as Record<string, unknown>;
  const types = Array.isArray(schema.type) ? schema.type : [schema.type];
  if (types.includes("object")) {
    expect(schema.additionalProperties, `${path}.additionalProperties`).toBe(false);
    expect(schema.properties, `${path}.properties`).toBeTypeOf("object");
    expect(Array.isArray(schema.required), `${path}.required`).toBe(true);
    const propertyKeys = Object.keys(schema.properties as Record<string, unknown>).sort();
    expect([...(schema.required as string[])].sort(), `${path}.required`).toEqual(propertyKeys);
  }
  for (const [key, child] of Object.entries(schema)) {
    assertStrictObjectGraph(child, `${path}.${key}`);
  }
}

function naturalCase001Reproduction(): Record<string, unknown> {
  return {
    hypothesisId: "hyp-1",
    request: {
      method: "POST",
      path: "/api/users/register",
      body: { email: "ada@example.test" },
    },
    expected: {
      status: 500,
      bodyContains: "user registration failed",
      logContains: ["USER_REGISTRATION_UNHANDLED"],
    },
    reason: "Exercise the reported email-only registration request and compare its correlated failure log.",
  };
}

describe("Reproducer Structured Outputs compatibility", () => {
  it("uses a strict-compatible object graph for every nested object", () => {
    expect(() => ajv.compile(REPRODUCER_JSON_SCHEMA)).not.toThrow();
    assertStrictObjectGraph(REPRODUCER_JSON_SCHEMA);
    const requestProperties = (REPRODUCER_JSON_SCHEMA.properties.request as { properties: Record<string, unknown> }).properties;
    expect(requestProperties).not.toHaveProperty("headers");
    expect(requestProperties).not.toHaveProperty("query");
  });

  it("accepts and deterministically decodes the case-001 provider fixture", async () => {
    const fixture = JSON.parse(await readFile(resolve("tests/fixtures/agentic/reproducer-case-001.json"), "utf8")) as unknown;
    expect(validateReproducer(fixture)).toBe(true);
    const parsed = reproducerProviderResponseSchema.safeParse(fixture);
    expect(parsed.success).toBe(true);
    if (!parsed.success) throw parsed.error;
    expect(parsed.data).toEqual(naturalCase001Reproduction());
    expect(reproducerDecisionSchema.safeParse(parsed.data).success).toBe(true);
  });

  it("keeps malformed requests rejected by provider and runtime validation", async () => {
    const fixture = JSON.parse(await readFile(resolve("tests/fixtures/agentic/reproducer-case-001.json"), "utf8")) as Record<string, unknown>;
    const request = fixture.request as Record<string, unknown>;
    const expected = fixture.expected as Record<string, unknown>;
    const malformedProvider = [
      { ...fixture, request: { ...request, method: "TRACE" } },
      { ...fixture, request: { ...request, path: "api/users/register" } },
      { ...fixture, expected: { ...expected, status: 99 } },
      { ...fixture, expected: { ...expected, logContains: [""] } },
      { ...fixture, expected: { ...expected, unexpected: true } },
    ];
    const natural = naturalCase001Reproduction();
    const naturalRequest = natural.request as Record<string, unknown>;
    const naturalExpected = natural.expected as Record<string, unknown>;
    const malformedRuntime = [
      { ...natural, request: { ...naturalRequest, method: "TRACE" } },
      { ...natural, request: { ...naturalRequest, path: "api/users/register" } },
      { ...natural, expected: { ...naturalExpected, status: 99 } },
      { ...natural, expected: { ...naturalExpected, logContains: [""] } },
      { ...natural, expected: { ...naturalExpected, unexpected: true } },
    ];

    for (let index = 0; index < malformedProvider.length; index += 1) {
      expect(validateReproducer(malformedProvider[index])).toBe(false);
      expect(reproducerProviderResponseSchema.safeParse(malformedProvider[index]).success).toBe(false);
      expect(reproducerDecisionSchema.safeParse(malformedRuntime[index]).success).toBe(false);
    }
  });

  it("rejects malformed encoded body entries before runtime decoding", async () => {
    const fixture = JSON.parse(await readFile(resolve("tests/fixtures/agentic/reproducer-case-001.json"), "utf8")) as Record<string, unknown>;
    const request = fixture.request as Record<string, unknown>;
    const malformed = {
      ...fixture,
      request: { ...request, body: { objectEntries: [{ key: "", value: "ada@example.test" }] } },
    };
    expect(validateReproducer(malformed)).toBe(false);
    expect(reproducerProviderResponseSchema.safeParse(malformed).success).toBe(false);
  });
});

describe("Verifier Structured Outputs compatibility", () => {
  const valid = {
    outcome: "verified",
    hypothesisId: "hyp-1",
    explanation: "Source and correlated runtime evidence establish the same causal mechanism.",
    evidenceIds: ["ev-source-1", "ev-http-1"],
    missingEvidenceRequest: null,
    unsupportedClaims: [],
  };

  it("uses a strict-compatible object graph and accepts the runtime contract", () => {
    expect(() => ajv.compile(VERIFIER_JSON_SCHEMA)).not.toThrow();
    assertStrictObjectGraph(VERIFIER_JSON_SCHEMA);
    expect(validateVerifier(valid)).toBe(true);
    expect(verifierDecisionSchema.safeParse(valid).success).toBe(true);
  });

  it("keeps enums, required fields, nullable values, and non-empty evidence aligned", () => {
    const malformed = [
      { ...valid, outcome: "maybe" },
      { ...valid, hypothesisId: "" },
      { ...valid, explanation: "" },
      { ...valid, evidenceIds: [""] },
