    const tool = createExecuteReproductionTool({ baseUrl, correlationId: () => "repro-supporting-mismatch" });
    const result = await tool({
      ...reproductionInput,
      expectations: {
        ...reproductionInput.expectations,
        supporting: { logContains: ["USER_REGISTRATION_UNHANDLED", "profile"] },
      },
